-- ============================================
-- Table structure for table `akun`
-- Includes OTP system for password reset:
-- - reset_otp: 6-digit OTP code
-- - reset_otp_expire: OTP expiration time (5 minutes)
-- - reset_otp_attempts: Failed attempt counter (max 3)
-- - reset_otp_last_attempt: Last attempt timestamp (for cooldown)
-- ============================================

DROP TABLE IF EXISTS `akun`;
CREATE TABLE `akun` (
  `id_akun` int(11) NOT NULL AUTO_INCREMENT,
  `nama_lengkap` varchar(50) NOT NULL,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `email` varchar(100) DEFAULT NULL,
  `foto_profil` varchar(255) DEFAULT NULL,
  `background_profil` varchar(255) DEFAULT NULL,
  `reset_otp` varchar(6) DEFAULT NULL,
  `reset_otp_expire` datetime DEFAULT NULL,
  `reset_otp_attempts` int(11) DEFAULT 0,
  `reset_otp_last_attempt` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_akun`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

