DROP TABLE IF EXISTS `pemesanan`;
CREATE TABLE `pemesanan` (
  `id_pemesanan` int(11) NOT NULL AUTO_INCREMENT,
  `id_akun` int(11) NOT NULL,
  `id_destinasi` int(11) NOT NULL,
  `jumlah_orang` int(11) NOT NULL,
  `asal` varchar(50) NOT NULL,
  `tanggal_berangkat` date NOT NULL,
  `tanggal_pulang` date NOT NULL,
  `status` enum('Pending','Accepted','Rejected') NOT NULL DEFAULT 'Pending',
  PRIMARY KEY (`id_pemesanan`),
  KEY `fk_pemesanan_akun` (`id_akun`),
  KEY `fk_pemesanan_destinasi` (`id_destinasi`),
  CONSTRAINT `fk_pemesanan_akun` FOREIGN KEY (`id_akun`) REFERENCES `akun` (`id_akun`) ON DELETE CASCADE,
  CONSTRAINT `fk_pemesanan_destinasi` FOREIGN KEY (`id_destinasi`) REFERENCES `destinasi` (`id_destinasi`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

